extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_main_scene()
	if not check("basket", basket != null, "La scena principale basket.tscn deve istanziarsi correttamente"):
		return

	check("freeze_fn", has_function(basket, "activate_freeze_powerup"), "basket.gd deve avere il metodo activate_freeze_powerup()")
	check("alchemy_fn", has_function(basket, "activate_alchemy_powerup"), "basket.gd deve avere il metodo activate_alchemy_powerup()")

	var falling_items := get_tree().get_nodes_in_group("falling_items")
	check("items_in_group", falling_items.size() > 0, "Gli elementi generati all'inizio devono appartenere al gruppo falling_items")

	var first_item: Node2D = falling_items[0] as Node2D
	var prev_y: float = first_item.position.y

	call_if_exists(basket, "activate_freeze_powerup")
	await wait_seconds(0.3)
	check("is_frozen", abs(first_item.position.y - prev_y) < 1.0, "Dopo activate_freeze_powerup() gli oggetti del gruppo falling_items non devono scendere")

	var rocks_before := get_tree().get_nodes_in_group("rocks")
	check("rocks_present", rocks_before.size() > 0, "Ci devono essere rocce nel gruppo rocks")

	call_if_exists(basket, "activate_alchemy_powerup")
	await wait_frames(2)
	var rocks_after := get_tree().get_nodes_in_group("rocks")
	var active_rocks_count: int = 0
	for r in rocks_after:
		if is_instance_valid(r) and not r.is_queued_for_deletion():
			active_rocks_count += 1
	check("alchemy_done", active_rocks_count == 0, "Dopo activate_alchemy_powerup() tutte le rocce devono essere state rimosse e sostituite")

